 s=read(RUN/'summary.json');v=read(RUN/'verification.json');rep=read(RUN/'reproduction.json');sel=read(RUN/'selection.json');unc=read(RUN/'uncertainty.json');diag=read(RUN/'diagnostics.json');assert len(s)==v['accounts']==36 and rep['all_bytes_equal'] and not sel['passed'];rows=[];base=[];annual=[];cost=[];ci=[]
