 if 'id="residual-followup"' not in old:p.write_text(old.replace('<h1>','<p id="residual-followup" class="boundary">추가36계좌: <a href="btc-residual-research.html">잔여현금 헤지 캐리 검증 ↗</a></p><h1>',1))
 files=['btc-residual-research.html','btc-web-research.html','downloads/btc-residual-evidence.zip','downloads/btc-residual-evidence.json','downloads/btc-residual-summary.csv','EXPERIMENT_BTC_RESIDUAL_CARRY_20261002.md','BTC_WEB_RESEARCH_20261002.md','assets/btc-continuation.css','assets/icon.svg'];out=ROOT/'runs/btc-residual-report-20261002';out.mkdir(exist_ok=True);(out/'public-manifest.json').write_bytes(canonical({n:{'sha256':sha((DOC/n).read_bytes()),'bytes':(DOC/n).stat().st_size} for n in files}));print(json.dumps({'accounts':len(rows),'files':len(files)}))
